declare(strict_types=1);require_once __DIR__.'/includes/admin_auth.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('shipping_services.php');verify_csrf();$id=filter_input(INPUT_POST,'service_id',FILTER_VALIDATE_INT);if(!$id){flash('warning','Layanan tidak valid.');redirect('shipping_services.php');}$pdo->prepare('UPDATE shipping_services SET is_active=IF(is_active=1,0,1),updated_at=NOW() WHERE id=:id')->execute(['id'=>$id]);log_admin_activity($pdo,'shipping_service_toggle','Mengubah status layanan #'.$id);flash('success','Status layanan berhasil diubah.');redirect('shipping_services.php');
